 const mq=window.matchMedia('(min-width:801px)');
 let frame=0;
 const specs=[
  ['🚀','OUR BEGINNING','The story of A&N Overseas'],
  ['◎','WHY WE BEGIN','Our purpose & inspiration'],
  ['▤','GLOBAL DIRECTORY','Explore universities'],
  ['◆','WHAT WE DO','Our services at a glance'],
  ['◉','OUR VISION','The future we are building']
 ];
 function restore(hero) {
  if(!hero||hero.dataset.an2ReferenceReady!=='1')return;
  hero.dataset.an2ReferenceReady='0';
  const brand=hero.querySelector('.an2-founder-brand');
  const quote=hero.querySelector('.an2-founder-quote');
  const sign=quote?.querySelector('.an2-quote-sign');
  const footer=quote?.querySelector('.an2-quote-footer');
  const nav=hero.querySelector(':scope > .an2-nav');
  const flags=hero.querySelector('.an2-ref-flagband .an2-flags-journey');
  const portrait=hero.querySelector(':scope > .an2-founder-person');
  const slogan=hero.querySelector(':scope > .an2-ref-slogan');
  if(nav){nav.querySelectorAll('a').forEach(a=>{if(a.dataset.an2OriginalLabel){a.textContent=a.dataset.an2OriginalLabel;delete a.dataset.an2OriginalLabel;}});hero.insertAdjacentElement('afterend',nav);}
  if(flags&&sign)sign.insertBefore(flags,sign.querySelector('.an2-founder-message-label'));
  if(portrait&&footer)footer.appendChild(portrait);
  if(slogan&&brand){slogan.innerHTML=slogan.dataset.an2OriginalHtml||slogan.innerHTML;slogan.classList.remove('an2-ref-slogan');brand.appendChild(slogan);delete slogan.dataset.an2OriginalHtml;}
  hero.querySelector('.an2-ref-flagband')?.remove();
  hero.querySelector('.an2-ref-worldtitle')?.remove();
  brand?.querySelector('.an2-ref-brandlock')?.remove();
  hero.classList.remove('an2-ref-hero');
 }
 function apply(){
  frame=0;
  const active=(location.hash||'').split('?')[0]==='#/aboutdetails';
  const story=document.getElementById('an2-story');
  const hero=story?.querySelector('.an2-founder-hero');
  if(!active||!mq.matches){
   document.body.classList.remove('an2-reference-active');
   if(hero)restore(hero);
   return;
  }
  if(!hero)return;
  if(hero.dataset.an2ReferenceReady==='1'){document.body.classList.add('an2-reference-active');return;}
  const brand=hero.querySelector('.an2-founder-brand');
  const quote=hero.querySelector('.an2-founder-quote');
  const nav=story.querySelector('.an2-nav');
  const flags=quote?.querySelector('.an2-flags-journey');
  const portrait=quote?.querySelector('.an2-founder-person');
  const slogan=brand?.querySelector('strong');
  if(!brand||!quote||!nav||!flags||!portrait||!slogan)return;
  hero.dataset.an2ReferenceReady='1';
  hero.classList.add('an2-ref-hero');
  const lock=document.createElement('div');
  lock.className='an2-ref-brandlock';
  lock.innerHTML='<span class="an2-ref-crest" role="img" aria-label="A&N Overseas golden globe emblem"></span><span class="an2-ref-company">A&amp;N OVERSEAS</span><span class="an2-ref-subtitle">EDUCATION &amp; CONSULTANCY</span>';
  brand.insertBefore(lock,brand.querySelector('img')?.nextSibling||brand.firstChild);
  slogan.dataset.an2OriginalHtml=slogan.innerHTML;
  slogan.innerHTML='ROOTED IN EXPERIENCE, <em>BUILT FOR YOUR FUTURE.</em>';
  slogan.classList.add('an2-ref-slogan');
  hero.appendChild(slogan);
  const title=document.createElement('div');
  title.className='an2-ref-worldtitle';
  title.innerHTML='FROM <span>HOME</span> TO THE <span>WORLD</span>';
  hero.appendChild(title);
  const band=document.createElement('div');band.className='an2-ref-flagband';
  hero.appendChild(band);band.appendChild(flags);
  hero.appendChild(portrait);
  hero.appendChild(nav);
  nav.querySelectorAll('a').forEach((a,i)=>{
   if(!specs[i])return;
   a.dataset.an2OriginalLabel=a.textContent.trim();
   a.innerHTML='<span class="an2-ref-icon" aria-hidden="true">'+specs[i][0]+'</span><span class="an2-ref-cardtext"><b>'+specs[i][1]+'</b><small>'+specs[i][2]+'</small></span>';
   a.setAttribute('aria-label',specs[i][1]+' — '+specs[i][2]);
  });
  document.body.classList.add('an2-reference-active');
  window.dispatchEvent(new Event('resize'));
 }
 function queue(){if(frame)cancelAnimationFrame(frame);frame=requestAnimationFrame(apply)}
 window.addEventListener('hashchange',()=>{queue();setTimeout(queue,140)});
 window.addEventListener('resize',queue,{passive:true});
 window.addEventListener('pageshow',queue);
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',queue,{once:true});else queue();
 const startup=()=>{const app=document.getElementById('app');if(!app)return;const observer=new MutationObserver(queue);observer.observe(app,{childList:true});queue()};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',startup,{once:true});else startup();
